from pathlib import Path
import json,psycopg2
P=Path('/private/tmp/twuanis-orch-final-01');out=[]
for n,run in [(128,'capacity-128'),(500,'capacity-500-60s'),(1000,'capacity-1000-60s'),(2000,'capacity-2000-60s'),(2000,'capacity-2000-paid'),(5000,'capacity-5000-indexed')]:
 D=P/'runs'/run;x=json.load(open(D/'capture-run-result.json'));payload=json.load(open(D/'finalize-request.json'));ev=payload['p_transcript'];body={**payload['p_envelope'],'immutableEvidence':ev};audit=json.load(open(D/'acquisition-audit.json'));cohorts=[a for a in audit if a['kind']=='engine-cohort'];evidence={'run':run,'requestedObservations':n,'execution':x['result']['execution'],'result':x['result'],'exactAcquired':{pop:len(body['evidence']['originalPrices'][pop])for pop in ['PRIVATE','BANK']},'roots':len(ev['records']),'nodes':len(ev['nodes']),'graphLogicalBytesUtf8':len(json.dumps(ev,ensure_ascii=False,separators=(',',':')).encode()),'transcriptLogicalBytesUtf8':len(json.dumps(body,ensure_ascii=False,separators=(',',':')).encode()),'network':{'httpCalls':x['queries'],'databaseHTTPCalls':sum(t['path'].startswith('/rest/')for t in x['timings']),'uploadedBytes':x['requestBytes'],'downloadedBytes':x['responseBytes']},'wallSeconds':x['wallMs']/1000,'appPeakRSSMiB':x['peakRss']/1048576,'workerCPUSeconds':(x['cpu']['user']+x['cpu']['system'])/1e6,'perEngine':[{'id':e['id'],'state':e['state'],'executed':e['executed'],'durationMs':e['durationMs'],'PRIVATE':e['result']['private']['n']if e['result']['private']else None,'BANK':e['result']['bank']['n']if e['result']['bank']else None}for e in body['engines']],'cohortMemberships':[{'engine':a['engine'],'populations':a['populations'],'rawN':len(a['before']),'eligibleN':len(a['items'])}for a in cohorts],'stages':{name:[t for t in x['timings']if name in t['path']]for name in ['witness_finalize','execution_commit']},'caveats':['Per-engine duration includes engine-specific acquisition/authorization/evidence capture; capture-exclusive CPU is not separately measured.','HTTP request totals are exact at the instrumentation boundary, not all internal SQL statements.','No provider invoice or hosted qualification.']}
 assert sum(evidence['exactAcquired'].values())==n
 c=psycopg2.connect('postgresql://postgres:postgres@127.0.0.1:54322/twuanis_orch_final_01_'+str(n));q=c.cursor();q.execute('select pg_column_size(transcript),octet_length(transcript::text) from twuanis_canonical_private.orchestrator_execution_witnesses where execution_id=%s',(x['result']['execution'],));v=q.fetchone();evidence['storedWitness']={'toastColumnBytes':v[0],'logicalPostgresTextBytes':v[1]}if v else None;q.execute('select pg_column_size(body),octet_length(body::text) from twuanis_canonical_private.execution_credit_reports where execution_id=%s',(x['result']['execution'],));v=q.fetchone();evidence['storedReport']={'toastColumnBytes':v[0],'logicalPostgresTextBytes':v[1]}if v else None;q.execute("select kind,quantity::text from twuanis_canonical_private.execution_credit_events where execution_id=%s order by id",(x['result']['execution'],));evidence['accountingEvents']=q.fetchall();c.close();out.append(evidence);(P/'capacity-evidence.json').write_text(json.dumps(out,indent=2));print(run,evidence['exactAcquired'],evidence['roots'],evidence['nodes'],flush=True)
